export type RunOutcome = 'pass' | 'fail' | 'none' | 'unknown'

const ANSI = /\u001b\[[0-9;?]*[ -/]*[@-~]/g
const NO_TESTS = /No test files found|No tests found/i
const SUMMARY_LINE = /^\s*(?:Tests|Test Files|Test Suites):?\s+(.+)$/gm
const FAILED = /(\d+)\s+failed/
const PASSED = /\d+\s+passed/
const FAILED_FILE = /^\s*(?:FAIL|❯|×)\s+((?:[A-Za-z]:)?[\w./\\-]+\.(?:test|spec)\.[cm]?[jt]sx?)\b/gm
const TRUNCATION_BANNER = /Output too large/
// What the model reads when Claude Code held a command for approval or refused it: the command never ran.
const NEVER_RAN = /requires approval|requested permissions? to use|haven't granted|denied by the .*classifier|permission(?: for this action)? (?:was |has been )?denied|can't be checked before it runs/i

export function stripAnsi(text: string): string {
  return text.replace(ANSI, '')
}

/**
 * Reads the runner's own summary line. There is no exit-code fallback on
 * purpose: a pipe, `|| true`, a crash before any test ran, or a truncated
 * tool result all leave no summary, and none of them is a verdict.
 */
export function runOutcome(output: string): RunOutcome {
  const text = stripAnsi(output)
  if (NO_TESTS.test(text)) {
    return 'none'
  }

  const summaries = [...text.matchAll(SUMMARY_LINE)].map(match => match[1] ?? '')
  if (summaries.some(summary => Number(FAILED.exec(summary)?.[1] ?? 0) > 0)) {
    return 'fail'
  }
  if (summaries.some(summary => PASSED.test(summary))) {
    return 'pass'
  }
  return 'unknown'
}

/** Test files the runner named as failed (Vitest `FAIL`/`❯` lines, Jest `FAIL` lines). */
export function failedFiles(output: string): string[] {
  const files = [...stripAnsi(output).matchAll(FAILED_FILE)].flatMap(match =>
    match[1] === undefined ? [] : [match[1].replace(/\\/g, '/')],
  )
  return [...new Set(files)]
}

/** Claude Code replaces a long tool result with a preview and this banner; the summary line is gone with it. */
export function isTruncated(output: string): boolean {
  return TRUNCATION_BANNER.test(output)
}

// The runner itself never started: no test ran (seen on dapr-agents: a global python without pytest, uv with no pytest).
const NOT_STARTED = /No module named ['"]?[\w.]+['"]?|Failed to spawn: \S+|command not found|is not recognized as an internal or external command/i

/**
 * Why the runner never started, when output with no summary says so; null otherwise. Asked only when no summary was
 * read, so a real run whose tests fail on an import error is still red.
 */
export function runnerDidNotStart(output: string): string | null {
  return NOT_STARTED.exec(stripAnsi(output))?.[0] ?? null
}

// Runners whose summary is recognised but not read yet, each by a line only its summary prints (tests/fixtures has
// the real output). A run of one is not an unread run, so it is named once instead of reported on every run.
const UNREAD_RUNNERS: readonly (readonly [string, RegExp])[] = [
  ['mocha', /^\s*\d+ passing \(\d+(?:\.\d+)?(?:ms|s|m)\)\s*$/m],
]

/** The runner whose summary this is, when it is one dope-tdd recognises but cannot read yet; null otherwise. */
export function unreadableRunner(output: string): string | null {
  const text = stripAnsi(output)
  return UNREAD_RUNNERS.find(([, summary]) => summary.test(text))?.[0] ?? null
}

/** An errored result whose text is a permission hold or refusal: not a run at all, so not even "unread". */
export function neverRan(output: string): boolean {
  return NEVER_RAN.test(output)
}

