const HERESTRING = /@['"]\r?\n/
// A heredoc opener: `<<EOF`, `<<-EOF`, `<<'EOF'`, `<< "EOF"`. Sticky, so it is tried at the `<<` just read.
const HEREDOC_OPEN = /<<-?\s*(['"]?)(\w+)\1/y

// A shell that runs what it reads on stdin: a heredoc fed to it is commands, not data.
const SHELL_READER = /^\s*(?:\w+=\S*\s+)*(?:\S*[\\/])?(?:bash|sh|zsh|dash|ksh)(?:\.exe)?(?:\s+-\w+)*\s*(?:<<|$)/

/**
 * The part of a segment that runs. A heredoc body fed to anything but a shell
 * (`cat > body.md <<'EOF'`, `tee`, `gh ... --body-file -`) is data: the
 * commands it quotes never run, so only the opener line counts.
 */
export function executedText(segment: string): string {
  const newline = segment.indexOf('\n')
  if (newline === -1) {
    return segment
  }
  const opener = segment.slice(0, newline)
  if (!/<<-?\s*(['"]?)\w+\1/.test(opener) || SHELL_READER.test(opener)) {
    return segment
  }
  return opener
}

// A command that runs what it reads on stdin: a heredoc fed to it is code, and the writes in it are real.
const INTERPRETER = /^\s*(?:\w+=\S*\s+)*(?:\S*[\\/])?(?:bash|sh|zsh|dash|ksh|python[\d.]*|py|node|deno|bun|ruby|perl|php|pwsh|powershell)(?:\.exe)?(?=\s|<|$)/i

/**
 * The part of a segment that can write files (the heredoc false positive, 2026-10-18). A heredoc fed to `cat`, `tee`
 * or `gh` is data: code and paths quoted in it write nothing, so only the opener line counts. One fed to an
 * interpreter or a shell is code: the whole segment counts, so a script's writes are still seen.
 */
export function writableText(segment: string): string {
  const newline = segment.indexOf('\n')
  if (newline === -1) {
    return segment
  }
  const opener = segment.slice(0, newline)
  if (!/<<-?\s*(['"]?)\w+\1/.test(opener) || INTERPRETER.test(opener)) {
    return segment
  }
  return opener
}

/**
 * Splits a command on `&&`, `||`, `;` and `|` outside quotes. A heredoc's body
 * stays with the command that opened it, verbatim, and what follows its
 * terminator is split as usual; a PowerShell here-string keeps the whole
 * command, because its body is data.
 */
export function commandSegments(command: string): string[] {
  if (HERESTRING.test(command)) {
    return [command]
  }
  const segments: string[] = []
  let current = ''
  let quote: '"' | "'" | null = null
  const pendingHeredocs: string[] = []
  for (let i = 0; i < command.length; i++) {
    const char = command[i] ?? ''
    if (quote !== null) {
      current += char
      if (char === '\\' && quote === '"' && i + 1 < command.length) {
        current += command[++i]
      } else if (char === quote) {
        quote = null
      }
      continue
    }
    if (char === '\\' && i + 1 < command.length) {
      current += char + command[++i]
      continue
    }
    if (char === '"' || char === "'") {
      quote = char
      current += char
      continue
    }
    if (char === '<' && command[i + 1] === '<') {
      HEREDOC_OPEN.lastIndex = i
      const opened = HEREDOC_OPEN.exec(command)
      if (opened !== null) {
        pendingHeredocs.push(opened[2] ?? '')
        current += opened[0]
        i += opened[0].length - 1
        continue
      }
    }
    if (char === '\n' && pendingHeredocs.length > 0) {
      // Each body runs to its terminator line; it belongs to the command that opened it and is never split.
      let rest = command.slice(i + 1)
      let body = ''
      for (const word of pendingHeredocs) {
        const lines = rest.split('\n')
        let taken = 0
        for (const line of lines) {
          taken++
          if (line.replace(/^\t+/, '').trimEnd() === word) {
            break
          }
        }
        const piece = lines.slice(0, taken).join('\n')
        body += (body === '' ? '' : '\n') + piece
        rest = lines.slice(taken).join('\n')
      }
      pendingHeredocs.length = 0
      current += '\n' + body
      i += body.length
      continue
    }
    const pair = command.slice(i, i + 2)
    if (pair === '&&' || pair === '||') {
      segments.push(current)
      current = ''
      i++
      continue
    }
    if (char === ';' || char === '|' || char === '\n') {
      segments.push(current)
      current = ''
      continue
    }
    current += char
  }
  segments.push(current)
  return segments.map(segment => segment.trim()).filter(segment => segment !== '')
}

export type LocatedSegment = { segment: string; cwd: string; vars: ShellVars }

/** The directory a command's segments run in: a `cd` moves every segment after it. Outside the root is still a place, named as it is. */
export const ELSEWHERE = '~'

function joinPath(base: string, target: string): string {
  const slashed = target.replace(/\\/g, '/')
  if (/^(?:[A-Za-z]:)?\//.test(slashed)) {
    return normalizePath(slashed)
  }
  return normalizePath(`${base.replace(/\\/g, '/')}/${slashed}`)
}

function normalizePath(path: string): string {
  const drive = /^([A-Za-z]:)(\/.*)?$/.exec(path)
  const prefix = drive === null ? (path.startsWith('/') ? '/' : '') : `${drive[1]}/`
  const rest = drive === null ? path.replace(/^\//, '') : (drive[2] ?? '').replace(/^\//, '')
  const out: string[] = []
  for (const part of rest.split('/')) {
    if (part === '' || part === '.') {
      continue
    }
    if (part === '..') {
      out.pop()
      continue
    }
    out.push(part)
  }
  return `${prefix}${out.join('/')}`
}

/**
 * Each segment with the directory it runs in. `root` is where the command
 * starts; a `cd` segment moves the segments after it (`cd` alone, `cd ~` and
 * `cd -` go somewhere this cannot see, so they go ELSEWHERE). A pipe does not
 * change directory; a subshell is not tracked.
 */
export function locatedSegments(command: string, root: string): LocatedSegment[] {
  let cwd = root.replace(/\\/g, '/').replace(/\/$/, '')
  let vars: ShellVars = new Map()
  const located: LocatedSegment[] = []
  for (const segment of commandSegments(command)) {
    located.push({ segment, cwd, vars })
    cwd = movedBy(cwd, segment, vars)
    vars = withAssignment(vars, segment)
  }
  return located
}

/**
 * Shell variables a command set before a segment (`R=/tmp/x;`, `export R=...`), by name (#69). Only what the command
 * itself assigns is known; the environment is not, so `$HOME` or `$(mktemp -d)` stays unexpanded.
 */
export type ShellVars = ReadonlyMap<string, string>

const ASSIGNMENT = /^(?:export\s+)?([A-Za-z_]\w*)=("[^"]*"|'[^']*'|\S*)$/

function withAssignment(vars: ShellVars, segment: string): ShellVars {
  const assignment = ASSIGNMENT.exec(segment.trim())
  if (assignment === null) {
    return vars
  }
  const [, name = '', raw = ''] = assignment
  const value = raw.replace(/^(['"])(.*)\1$/, '$2')
  const expanded = raw.startsWith("'") ? value : expandVariables(value, vars)
  const next = new Map(vars)
  // A value this cannot know (another variable, a command) makes the name unknown, not wrong.
  if (expanded === null) {
    next.delete(name)
  } else {
    next.set(name, expanded)
  }
  return next
}

/** `text` with the variables the command set put in; null when anything is left that the shell would expand. */
export function expandVariables(text: string, vars: ShellVars): string | null {
  const out = expandKnown(text, vars)
  return /\$|%\w+%|`/.test(out) ? null : out
}

/** `text` with the variables the command set put in, and every other `$NAME` or `${NAME}` left as it is. */
export function expandKnown(text: string, vars: ShellVars): string {
  return text.replace(/\$\{(\w+)\}|\$([A-Za-z_]\w*)/g, (whole: string, braced?: string, bare?: string) => vars.get(braced ?? bare ?? '') ?? whole)
}

// Commands that only read. `find` with -exec or -delete and `git` verbs that write are not among them.
const READS = /^\s*(?:cd|ls|dir|cat|type|head|tail|grep|rg|wc|pwd|echo|which|where|tree|stat|file|du|df|sort|uniq|true|find(?![^\n]*\s-(?:exec|execdir|delete|ok|fprint)\b)|git\s+(?:status|log|diff|show|branch|rev-parse|ls-files|blame|remote|config\s+--get))(?:\s|$)/
// An output redirect writes, whatever the command: `echo x > src/a.ts`. Stderr to a file descriptor or /dev/null does not.
const WRITES_OUTPUT = /(?:^|[^\d&>])>{1,2}(?!&)\s*(?!\/dev\/null)\S/

/** Only commands that read: nothing in it can change a file, so there is nothing to snapshot around it. */
export function isPureRead(command: string): boolean {
  const segments = commandSegments(command).map(executedText).filter(segment => segment.trim() !== '')
  return segments.length > 0 && segments.every(segment => READS.test(segment) && !WRITES_OUTPUT.test(segment))
}

/** Where the shell is after the whole command, starting from `start`: the next call starts there. */
export function cwdAfter(command: string, start: string): string {
  const located = locatedSegments(command, start)
  const last = located.at(-1)
  return last === undefined ? start.replace(/\\/g, '/').replace(/\/$/, '') : movedBy(last.cwd, last.segment, last.vars)
}

function movedBy(cwd: string, segment: string, vars: ShellVars): string {
  const cd = /^cd(?:\s+(.*))?$/.exec(segment.trim())
  if (cd === null) {
    return cwd
  }
  const quoted = (cd[1] ?? '').trim()
  const unquoted = quoted.replace(/^(['"])(.*)\1$/, '$2')
  // A target this cannot expand (`$SOMEWHERE`, `$(mktemp -d)`, `%TEMP%`) goes somewhere it cannot see (#69).
  const target = quoted.startsWith("'") ? unquoted : expandVariables(unquoted, vars)
  if (target === null || target === '' || target === '-' || target === '~' || target.startsWith('~/')) {
    return ELSEWHERE
  }
  if (cwd === ELSEWHERE) {
    return /^(?:[A-Za-z]:)?[\\/]/.test(target) ? joinPath('', target) : ELSEWHERE
  }
  return joinPath(cwd, target)
}

files.hooks/shellVerdict.ts:
// The decisions `checkShell` in register.tsx makes about a shell command, as plain data in and out (#59). The engine
// follows `$` only into functions declared in register.tsx, so that file gathers the inputs and carries out the
// result; what is decided lives here, where a unit test reaches it without the fake engine.
import { carriedOnAdvice, redUnlockAdvice, unreadableRunnerAdvice } from './advice.ts'
import type { Policy } from './config.ts'
import { moduleLabel, relativePath, sourcePathFor } from './mirror.ts'
import type { LayoutConfig } from './mirror.ts'

export type ShellWrite = { readonly module: string | null; readonly policy: Policy }

/**
 * Which modules a shell command's writes may not reach yet: `locked`, enforced with no unlock; `waiting`, unlocked
 * only by a carry-over from an earlier session, whose run this session it waits for, as an Edit does (#54).
 */
export function gateShellWrites(
  writes: readonly ShellWrite[],
  unlocked: Readonly<Record<string, string>>,
  inherited: Readonly<Record<string, number>>,
): { locked: string[]; waiting: string[] } {
  const locked = writes.flatMap(({ module, policy }) =>
    module !== null && policy === 'enforce' && unlocked[module] === undefined ? [module] : [],
  )
  const waiting = writes.flatMap(({ module, policy }) =>
    module !== null && policy === 'enforce' && unlocked[module] !== undefined && inherited[module] !== undefined ? [module] : [],
  )
  return { locked, waiting }
}

export type ShellGateInput = {
  /** The command writes the override record, which only dope-tdd writes (overrides.ts). */
  readonly writesRecord: boolean
  /** From gateShellWrites, after the approved overrides that cover them are taken out. */
  readonly locked: readonly string[]
  readonly waiting: readonly string[]
  readonly paused: boolean
}

export type ShellGateVerdict = { kind: 'deny-record' } | { kind: 'refuse'; locked: string[]; waiting: string[] } | { kind: 'go' }

/** The verdict on a shell command's writes before it runs (#59, 2026-10-18); register.tsx words the refusal and records it. */
export function shellGate(input: ShellGateInput): ShellGateVerdict {
  // The record is evidence of who approved what: refused even while paused, as an Edit to it is (fileGate.ts).
  if (input.writesRecord) {
    return { kind: 'deny-record' }
  }
  if (input.paused || (input.locked.length === 0 && input.waiting.length === 0)) {
    return { kind: 'go' }
  }
  return { kind: 'refuse', locked: [...input.locked], waiting: [...new Set(input.waiting)] }
}

export type FailureJudgement = {
  readonly outcome: 'pass' | 'fail'
  /** The failing tests that were failing before the change, named to the agent when the run counts as green. */
  readonly alreadyFailing: string[]
  /** What the caller records: the names as the module's known failures, as its red, or nothing. */
  readonly record: 'known' | 'red' | null
}

/**
 * A red run of the module's own test file, judged by which tests fail. Tests that were failing before the change
 * neither hide a red nor block a green: only the known failures, or fewer than the red with none new, is green.
 */
export function judgeFailures(
  names: readonly string[],
  state: { readonly knownFailures?: readonly string[]; readonly redFailures?: readonly string[] },
): FailureJudgement {
  const within = (set: readonly string[]) => names.length > 0 && set.length > 0 && names.every(name => set.includes(name))
  if (within(state.knownFailures ?? [])) {
    return { outcome: 'pass', alreadyFailing: [...names], record: null }
  }
  if (within(state.redFailures ?? []) && names.length < (state.redFailures ?? []).length) {
    return { outcome: 'pass', alreadyFailing: [...names], record: 'known' }
  }
  return { outcome: 'fail', alreadyFailing: [], record: names.length > 0 ? 'red' : null }
}

export type ShellReminderFacts = {
  readonly paused: boolean
  /** Sources the command changed with no test touched first. */
  readonly unguardedPaths: readonly string[]
  readonly alreadyFailing: readonly string[]
  /** The module whose own test those failures are in; null says "this module". */
  readonly alreadyFailingModule: string | null
  /** Why the runner did not start, when it did not. */
  readonly notStarted: string | null
  /** A runner dope-tdd cannot read, given only the first time it is seen, since it is said once. */
  readonly unreadableRunner: string | null
  /** Sources changed while a command that cannot write them ran. */
  readonly bystanders: readonly string[]
  /** The commented-out-code notes, already worded. */
  readonly commented: readonly string[]
  readonly redUnlocked: readonly string[]
  /** Modules whose carried-over unlock this run made active again, each with its test's absolute path. */
  readonly carriedOn: readonly { readonly module: string; readonly testPath: string }[]
  readonly passed: boolean
  /** The run's own advice line, last. */
  readonly advice: string | null
}

/** The lines appended to a shell command's result, in their fixed order; none while the guard is paused. */
export function shellReminders(facts: ShellReminderFacts, config: LayoutConfig, root: string): string[] {
  const { alreadyFailing } = facts
  return facts.paused
    ? []
    : [
        ...facts.unguardedPaths.map(path => `dope-tdd: ${path} changed through a shell command without a test touched first.`),
        ...(alreadyFailing.length === 0
          ? []
          : [
              `dope-tdd: ${facts.alreadyFailingModule === null ? 'this module' : moduleLabel(config, facts.alreadyFailingModule)} is green apart from ${alreadyFailing.length} test${alreadyFailing.length === 1 ? ' that was' : 's that were'} already failing before your change: ${alreadyFailing.slice(0, 3).join('; ')}${alreadyFailing.length > 3 ? '; …' : ''}.`,
            ]),
        ...(facts.notStarted === null ? [] : [`dope-tdd: the test runner did not start (${facts.notStarted}); nothing was counted. Run it the way this project runs its tests.`]),
        ...(facts.unreadableRunner === null ? [] : [unreadableRunnerAdvice(facts.unreadableRunner)]),
        ...facts.bystanders.map(path => `dope-tdd: ${path} changed while the command ran, but the command cannot have changed it (another editor or session?); not counted.`),
        ...facts.commented,
        ...facts.redUnlocked.map(module => redUnlockAdvice(moduleLabel(config, module), sourcePathFor(config, module))),
        ...facts.carriedOn.map(({ module, testPath }) => carriedOnAdvice(sourcePathFor(config, module), relativePath(root, testPath), facts.passed)),
        ...(facts.advice === null ? [] : [facts.advice]),
      ]
}

files.hooks/runPlan.ts:
// What a read test run does to the session's record, as plain data in and out (#59). `checkShell` in register.tsx
// gathers what needs `$` first (the imports of each failing test, whether a module has a test of its own), applies the
// plan in one state change, then remembers the unlocks it names across sessions.
import type { TddStats } from '../types'
import type { GuardConfig } from './config.ts'
import { classifyPath, pathKey, relativePath } from './mirror.ts'
import {
  closeCyclesForTest,
  recordCarriedRun,
  recordImporter,
  recordOtherPass,
  recordRedFor,
  recordRedUnlock,
  recordRun,
  recordRunTarget,
} from './stats.ts'

export function absolutePath(root: string, path: string): string {
  return /^([A-Za-z]:|[\\/])/.test(path) ? path : `${root}/${path}`
}

/** The test files the runner named as failed, as modules; empty when the output names none. */
function failedModules(root: string, files: readonly string[], config: GuardConfig): string[] {
  return files.flatMap(file => {
    const target = classifyPath(root, absolutePath(root, file), config)
    return target.kind === 'test' ? [target.module] : []
  })
}

/** The runner prints paths relative to where it ran; resolve them there, then name them from the root. */
export function failedTestPaths(root: string, runLocation: string | null, files: readonly string[]): string[] {
  return files.map(path => relativePath(root, /^(?:[A-Za-z]:|\/)/.test(path) ? path : `${runLocation}/${path}`))
}

/** The test files a red run failed, absolute and once each: those the runner named, and the one the command named. */
export function failingTestFiles(root: string, config: GuardConfig, failed: readonly string[], named: string | undefined): string[] {
  const target = named === undefined ? null : classifyPath(root, named, config)
  return [...new Set([...failed.map(path => absolutePath(root, path)), ...(named !== undefined && target?.kind === 'test' ? [named] : [])])]
}

export type RunFacts = {
  readonly outcome: 'pass' | 'fail'
  /** The test file the command names, absolute. */
  readonly named: string | undefined
  /** The run is filtered to some tests by name. */
  readonly filtered: boolean
  /** The modules the named test imports. */
  readonly namedImports: readonly string[]
  /** The failed test files, named from the root (`failedTestPaths`); empty for a green. */
  readonly failed: readonly string[]
  /** The modules each failing test file imports, keyed by its absolute path (`failingTestFiles`). */
  readonly importsOf: Readonly<Record<string, readonly string[]>>
  /** Whether a module has a test of its own, for each module a failing test imports. */
  readonly ownTest: Readonly<Record<string, boolean>>
  /** The runner always runs the whole folder (runners.ts, runsWholeFolder). */
  readonly wholeFolder?: boolean
  /** Code files the command names that are not tests by the stack's rule, absolute (runners.ts, namedOtherFiles). */
  readonly namedOther?: readonly string[]
}

/** The red elsewhere of a whole-folder run that did not say which files failed. */
export const UNNAMED_FAILURE = 'a file the output did not name'

export type RunPlan = {
  readonly state: TddStats
  /** Modules a red unlocked, in order, repeats kept: one reminder line each. */
  readonly redUnlocked: string[]
  /** Unlocks to remember across sessions, in order. */
  readonly remember: { module: string; testPath: string }[]
  /** Failed test files when the current module's own did not fail: a red elsewhere. */
  readonly elsewhere: string[]
  /** Modules whose carried-over unlock this run made active again (#54). */
  readonly carriedOn: string[]
  /** The run closed the current module's own cycle, before it closed other modules' (#41). */
  readonly ownCycleClosed: boolean
  /** False for a green that is not about the current module: it must not close its cycle or start its catch check. */
  readonly countsForCurrent: boolean
}

/** A read run, red or green, applied to the record. */
export function applyRun(s: TddStats, facts: RunFacts, root: string, config: GuardConfig, nowMs: number): RunPlan {
  const { outcome, named, filtered, namedImports } = facts
  const target = named === undefined ? null : classifyPath(root, named, config)
  const redUnlocked: string[] = []
  const remember: { module: string; testPath: string }[] = []
  let elsewhere: string[] = []
  let targeted = s
  const current = s.current
  // The run is the current module's test, or a test that imports it: the band stays on the module being worked on.
  const keepsCurrent =
    current !== null && named !== undefined && (pathKey(current.testPath) === pathKey(named) || namedImports.includes(current.module))
  // A run that names only files outside the layout (`node --test tools/x.spec-node.ts`) is about those files, unless
  // one imports the current module. Seen live 2026-10-18: such a run gave the current module a red and a cycle it never had.
  const outsideFiles = named === undefined ? (facts.namedOther ?? []) : []
  const outside = outsideFiles.length > 0 && !(current !== null && namedImports.includes(current.module))
  if (target?.kind === 'test' && named !== undefined && !keepsCurrent) {
    // A red on the module's own test is the evidence a touch stands for: it unlocks the module, and the band follows it.
    const testPath = named
    if (outcome === 'fail' && s.unlocked[target.module] === undefined) {
      targeted = recordRedUnlock(targeted, target.module, testPath, true)
      remember.push({ module: target.module, testPath })
      redUnlocked.push(target.module)
    } else {
      targeted = recordRunTarget(targeted, target.module)
    }
  }
  if (outcome === 'fail') {
    const { failed } = facts
    // Every test file the runner named as failed unlocks its module the same way, without becoming current.
    for (const path of failed) {
      const seen = classifyPath(root, absolutePath(root, path), config)
      if (seen.kind === 'test' && targeted.unlocked[seen.module] === undefined) {
        targeted = recordRedUnlock(targeted, seen.module, absolutePath(root, path), false)
        remember.push({ module: seen.module, testPath: absolutePath(root, path) })
        redUnlocked.push(seen.module)
      }
    }
    // A failing test is a red for every module it imports: unlocked if they were not, and their cycle saw red.
    const failingTests = failingTestFiles(root, config, failed, named)
    const coveredByFailure: string[] = []
    for (const testFile of failingTests) {
      for (const module of facts.importsOf[testFile] ?? []) {
        coveredByFailure.push(module)
        targeted = recordImporter(targeted, module, testFile)
        if (targeted.unlocked[module] === undefined && facts.ownTest[module] === false) {
          targeted = recordRedUnlock(targeted, module, testFile, false)
          remember.push({ module, testPath: testFile })
          redUnlocked.push(module)
        }
      }
    }
    const own = targeted.current?.module
    // Only a module this test now unlocks: one with a test of its own (#37) would be left red with nothing to close it.
    for (const module of [...new Set(coveredByFailure)].filter(module => module !== own && targeted.unlocked[module] !== undefined)) {
      targeted = recordRedFor(targeted, module, nowMs)
    }
    // The suite is red; the module is red only if its own test, or a test that imports it, is among the files that failed.
    const ownFailed = own !== undefined && (failedModules(root, failed, config).includes(own) || coveredByFailure.includes(own))
    elsewhere = failed.length > 0 && own !== undefined && !ownFailed ? [...failed] : []
    // A whole-folder run that named no failed file says only that something failed somewhere: it is not the current
    // module's red (seen live, 2026-10-18: a kit run read without its file headers turned the band RED). A run of the
    // module's own test, or a suite that does not name files (vitest's summary), keeps its old reading.
    if (facts.wholeFolder === true && failed.length === 0 && own !== undefined) {
      elsewhere = [UNNAMED_FAILURE]
    }
    if (outside && own !== undefined) {
      elsewhere = outsideFiles.map(path => relativePath(root, path))
    }
  }
  // A green of another module's own test, when the band could not follow it there (that module is not unlocked) and
  // the test does not import the current module, says nothing about the current module (seen on dope-tdd, 2026-10-18).
  const otherGreen =
    outcome === 'pass' && target?.kind === 'test' && !keepsCurrent && targeted.current?.module !== target.module ? target.module : null
  const outsideGreen = outcome === 'pass' && outside
  const countsForCurrent = otherGreen === null && !outsideGreen
  let afterRun = outsideGreen
    ? recordOtherPass(targeted, null, nowMs)
    : otherGreen === null
      ? recordRun(targeted, outcome === 'pass', nowMs, elsewhere)
      : recordOtherPass(targeted, otherGreen, nowMs)
  const ownCycleClosed = afterRun.cycles > s.cycles
  const carriedOn: string[] = []
  // #54: a whole-file run of the test behind a carried-over unlock, red or green, is the run its first edit waits for.
  // Only a run that names the file: a suite run need not have run it, and a filtered one ran only some of it.
  if (named !== undefined && !filtered) {
    const carried = Object.keys(afterRun.inherited).filter(module => {
      const testPath = afterRun.unlocked[module]
      return testPath !== undefined && pathKey(testPath) === pathKey(named)
    })
    if (carried.length > 0) {
      afterRun = recordCarriedRun(afterRun, carried, nowMs)
      carriedOn.push(...carried)
    }
  }
  if (outcome === 'pass' && !outsideGreen && (named !== undefined || !filtered)) {
    // The test file passed, or the whole suite did: no other module it is the test for stays red behind it.
    afterRun = closeCyclesForTest(afterRun, named ?? null, afterRun.current?.module, nowMs)
  }
  return { state: afterRun, redUnlocked, remember, elsewhere, carriedOn, ownCycleClosed, countsForCurrent }
}

