// Override with a reason (the standard, "Guardrails, not walls"; v1, 2026-10-18). Every guardrail can be passed, never
// silently: a request names its scope, kind, reason and what ends it, and no agent approves its own exception. In v1
// the approver is the person (a reviewer model is the next step). The record is a file in the repo, so who approved
// what shows in the pull request's diff. Pure: register.tsx reads and writes the file and asks the person.
import type { Decider, Override, OverrideRequest, OverrideStatus } from '../types'

export const OVERRIDES_FILE = 'dope-tdd.overrides.json'

export const KINDS = ['spike', 'hotfix', 'generated', 'legacy', 'other'] as const
export const SCOPES = ['change', 'module', 'pause'] as const
export type { Decider, Override, OverrideKind, OverrideRequest, OverrideScope, OverrideStatus } from '../types'

export type OverrideLimits = { pauseMaxMinutes: number }

const MINUTE = 60_000
const DAY = 24 * 60 * MINUTE
const AGED_MS = 7 * DAY
const MIN_REASON = 30
// Phrases that say only that the guard was in the way. A reason says what, why and what happens next.
const EMPTY_PHRASES = ['needed to proceed', 'need to proceed', 'to unblock myself', 'the guard is blocking', 'tdd is in the way']

/** Why a request is refused before anyone is asked, or null when it is complete. Checks form only; the approver judges the rest. */
export function checkRequest(request: OverrideRequest, limits: OverrideLimits): string | null {
  if (!(KINDS as readonly string[]).includes(request.kind)) {
    return `kind must be one of: ${KINDS.join(', ')}`
  }
  if (!(SCOPES as readonly string[]).includes(request.scope)) {
    return `scope must be one of: ${SCOPES.join(', ')}`
  }
  if (request.scope === 'pause') {
    if (limits.pauseMaxMinutes <= 0) {
      return 'pause is turned off for this repo (dope-tdd.json)'
    }
    if (request.minutes === null || !Number.isInteger(request.minutes) || request.minutes < 1) {
      return 'a pause needs minutes: how long, as a whole number'
    }
    if (request.minutes > limits.pauseMaxMinutes) {
      return `a pause is at most ${limits.pauseMaxMinutes} minutes`
    }
  } else if (request.module === null || request.module === '') {
    return 'a change or module override names the file it is for'
  }
  if (request.scope === 'module' && (request.until === null || request.until.trim() === '')) {
    return 'a module override needs "until": what ends it'
  }
  const reason = request.reason.trim()
  const empty = EMPTY_PHRASES.find(phrase => reason.toLowerCase().includes(phrase))
  if (empty !== undefined) {
    return `"${empty}" is not a reason: say what, why and what happens next`
  }
  if (reason.length < MIN_REASON) {
    return 'the reason must say what, why and what happens next'
  }
  return null
}

/**
 * Who decides, at the moment of asking. A person asking is the approver. A hotfix always passes, so the guard is never
 * in the way of recovery, and is debt until a test is written. An agent waits for a person, and with nobody there it
 * is denied: it stops and reports rather than approving itself.
 */
export function decideAtRequest(request: OverrideRequest, attended: boolean): { status: OverrideStatus; decidedBy: Decider | null } {
  if (request.by === 'human') {
    return { status: 'approved', decidedBy: 'human' }
  }
  if (request.kind === 'hotfix') {
    return { status: 'approved', decidedBy: 'hotfix rule' }
  }
  return attended ? { status: 'pending', decidedBy: null } : { status: 'denied', decidedBy: 'unattended' }
}

function isOpen(o: Override): boolean {
  return o.status === 'approved' && o.endedAtMs === null
}

/** The hard part of the rising bar: one request waits at a time, and an override left open past a week blocks the next. */
export function refuseByBar(record: readonly Override[], _request: OverrideRequest, nowMs: number): string | null {
  if (record.some(o => o.status === 'pending')) {
    return 'another override request is already waiting for a decision'
  }
  const aged = record.find(o => isOpen(o) && o.scope === 'module' && nowMs - o.atMs > AGED_MS)
  if (aged !== undefined) {
    const days = Math.floor((nowMs - aged.atMs) / DAY)
    return `an override on ${aged.module} has been open ${days} days: end it (/tdd override end ${aged.module}) before asking for another`
  }
  return null
}

function ordinal(n: number): string {
  const suffix = n % 100 >= 11 && n % 100 <= 13 ? 'th' : ({ 1: 'st', 2: 'nd', 3: 'rd' } as Record<number, string>)[n % 10] ?? 'th'
  return `${n}${suffix}`
}

/** The soft part: what the approver is told about this request's history, so a repeat is seen as one. */
export function requestNotes(record: readonly Override[], request: OverrideRequest, nowMs: number): string[] {
  const sameModule = request.module === null ? 0 : record.filter(o => o.module === request.module && nowMs - o.atMs < 7 * DAY).length
  const lastDay = record.filter(o => nowMs - o.atMs < DAY).length
  return [
    ...(sameModule > 0 ? [`${ordinal(sameModule + 1)} override request on ${request.module} this week`] : []),
    ...(lastDay > 0 ? [`${ordinal(lastDay + 1)} override request in the last day`] : []),
  ]
}

/**
 * The override that lets a locked edit to this module through now, or null. Only the session that asked may use it:
 * another agent in the same folder sees it on the band but cannot spend it (own your space, 2026-10-18).
 */
export function coveringOverride(record: readonly Override[], module: string, nowMs: number, session?: string): Override | null {
  return (
    record.find(o => {
      if (!isOpen(o) || (o.session !== undefined && session !== undefined && o.session !== session)) {
        return false
      }
      if (o.scope === 'pause') {
        return nowMs < o.atMs + (o.minutes ?? 0) * MINUTE
      }
      return o.module === module && (o.scope === 'module' || o.edits.length === 0)
    }) ?? null
  )
}

export function recordEdit(record: readonly Override[], id: string, path: string): Override[] {
  return record.map(o => (o.id === id ? { ...o, edits: [...o.edits, path] } : o))
}

/** Ends a module's open overrides, or with `pause`, ends and settles every pause. */
export function endOverride(record: readonly Override[], target: string, nowMs: number): Override[] {
  return record.map(o => {
    if (target === 'pause' && o.scope === 'pause' && o.status === 'approved') {
      return { ...o, endedAtMs: o.endedAtMs ?? nowMs, settledAtMs: o.settledAtMs ?? nowMs }
    }
    return o.module === target && o.status !== 'denied' && o.endedAtMs === null ? { ...o, endedAtMs: nowMs } : o
  })
}

/** Resuming early: open pauses stop letting edits through now; their untested edits stay debt until settled. */
export function closePauses(record: readonly Override[], nowMs: number): Override[] {
  return record.map(o => (isOpen(o) && o.scope === 'pause' ? { ...o, endedAtMs: nowMs } : o))
}

/**
 * Whether a person can answer a request now. `isInteractive` is false for every SDK host, the desktop app among them
 * (live trial, 2026-10-18), so a surface drawing the session counts too; a plain -p run has none.
 */
export function isAttended(isInteractive: boolean, surfaces: readonly string[]): boolean {
  return isInteractive || surfaces.length > 0
}

/** What an approved override still lets through now, for the band; null once it is spent, ended or out of time. */
export function overrideLeft(o: Override, nowMs: number): string | null {
  if (!isOpen(o)) {
    return null
  }
  if (o.scope === 'pause') {
    const leftMs = o.atMs + (o.minutes ?? 0) * MINUTE - nowMs
    return leftMs > 0 ? `${Math.ceil(leftMs / MINUTE)}m left` : null
  }
  if (o.scope === 'change') {
    return o.edits.length === 0 ? '1 edit left' : null
  }
  return `until ${o.until ?? 'it is ended'}`
}

/** For an /tdd override end that matched nothing: what is open, and how to end it. */
export function endHint(record: readonly Override[], nowMs: number): string {
  const open = record.filter(o => overrideLeft(o, nowMs) !== null)
  if (open.length === 0) {
    return 'Nothing is open.'
  }
  const listed = open.map(o => `${o.module ?? 'pause'} (${o.scope} · ${o.kind}, ${overrideLeft(o, nowMs)})`).join('; ')
  return `Open: ${listed}. End one with /tdd override end <module>, or /tdd override end pause.`
}

export function expiredPauses(record: readonly Override[], nowMs: number): Override[] {
  return record.filter(o => isOpen(o) && o.scope === 'pause' && nowMs >= o.atMs + (o.minutes ?? 0) * MINUTE)
}

export function pauseSummary(pause: Override): string {
  const head = `dope-tdd is back on after ${pause.minutes ?? 0}m (${pause.reason.trim()})`
  if (pause.edits.length === 0) {
    return `${head}: no edits while paused.`
  }
  const files = new Set(pause.edits).size
  const edits = `${pause.edits.length} edit${pause.edits.length === 1 ? '' : 's'}`
  return `${head}: ${edits} to ${files} file${files === 1 ? '' : 's'} while paused, none tested. Pin them with /dope-tdd:pin.`
}

/** What the receipt keeps showing until someone deals with it: open module overrides, hotfixes, and paused edits. */
export function openDebt(record: readonly Override[]): Override[] {
  return record.filter(o => {
    if (o.status !== 'approved') {
      return false
    }
    if (o.scope === 'pause') {
      return o.edits.length > 0 && o.settledAtMs === null
    }
    return o.endedAtMs === null && (o.scope === 'module' || o.kind === 'hotfix')
  })
}

function isOverride(value: unknown): value is Override {
  const o = value as Partial<Override> | null
  return (
    typeof o === 'object' &&
    o !== null &&
    typeof o.id === 'string' &&
    typeof o.atMs === 'number' &&
    typeof o.reason === 'string' &&
    (KINDS as readonly string[]).includes(o.kind ?? '') &&
    (SCOPES as readonly string[]).includes(o.scope ?? '') &&
    ['pending', 'approved', 'denied'].includes(o.status ?? '')
  )
}

/** A missing or broken file reads as no overrides: the record is evidence, and a broken one is not trusted. */
export function parseRecord(text: string | null): Override[] {
  if (text === null) {
    return []
  }
  try {
    const parsed = JSON.parse(text) as { overrides?: unknown }
    const list = Array.isArray(parsed.overrides) ? parsed.overrides : []
    return list.filter(isOverride).map(o => ({ ...o, settledAtMs: o.settledAtMs ?? null, edits: Array.isArray(o.edits) ? o.edits : [] }))
  } catch {
    return []
  }
}

export function serializeRecord(record: readonly Override[]): string {
  return `${JSON.stringify({ overrides: record }, null, 2)}\n`
}

/** A model's decision names the model and its effort, so it never reads as a person's sign-off. */
export function deciderLabel(o: Override): string {
  if (o.decidedBy === 'model' && o.review !== undefined) {
    return `model ${o.review.model} (${o.review.effort})`
  }
  return o.decidedBy ?? 'unknown'
}

// One "key: value" row per override, so the app can show /tdd as a table (2026-10-18).
function lineFor(o: Override): string {
  const head = `override ${o.module ?? 'pause'}: ${o.scope} · ${o.kind}`
  if (o.status === 'pending') {
    return `${head} · waiting for a person`
  }
  if (o.status === 'denied') {
    return `${head} · denied by ${deciderLabel(o)}${o.note === null ? '' : `: ${o.note}`}`
  }
  const why = o.decidedBy === 'model' && o.review !== undefined && o.review.reason !== '' ? `: ${o.review.reason}` : ''
  const state =
    o.scope === 'pause'
      ? o.edits.length > 0 && o.settledAtMs === null
        ? `DEBT: ${o.edits.length} edit${o.edits.length === 1 ? '' : 's'} untested`
        : null
      : o.endedAtMs !== null
        ? 'ENDED'
        : o.kind === 'hotfix'
          ? 'DEBT: no test yet'
          : o.scope === 'module'
            ? 'OPEN'
            : null
  const parts = [
    `approved by ${deciderLabel(o)}${why}`,
    ...(o.until === null ? [] : [`until ${o.until}`]),
    ...(o.scope === 'pause' ? [`${o.minutes ?? 0}m`] : []),
    ...(state === null ? [] : [state]),
  ]
  return `${head} · ${parts.join(' · ')}`
}

/** For /tdd and the receipt: the rate per cycle first, so 2 in 40 reads differently from 2 in 3. */
export function formatOverrides(record: readonly Override[], cycles: number): string[] {
  if (record.length === 0) {
    return []
  }
  const approved = record.filter(o => o.status === 'approved').length
  const denied = record.filter(o => o.status === 'denied').length
  const waiting = record.filter(o => o.status === 'pending').length
  const header = [
    `overrides: ${approved} approved in ${cycles} cycles`,
    ...(denied > 0 ? [`${denied} denied`] : []),
    ...(waiting > 0 ? [`${waiting} waiting`] : []),
  ].join(' · ')
  return [header, ...record.map(lineFor)]
}

files.hooks/requestPlan.ts:
// The override decisions (#59, 2026-10-18): out of register.tsx, so the gate's own catch check covers them. Given the
// request, the record and what the shell found out (whether a person is there, the model's review, this session),
// it says what to record, what to tell the person, and what to answer the agent. register.tsx reads and writes the
// record, asks the model, and shows the notices.
import type { Override, OverrideKind, OverrideRequest, OverrideScope, Review } from '../types'
import {
  OVERRIDES_FILE,
  checkRequest,
  closePauses,
  coveringOverride,
  decideAtRequest,
  endHint,
  endOverride,
  expiredPauses,
  pauseSummary,
  recordEdit,
  refuseByBar,
  requestNotes,
} from './overrides.ts'
import type { OverrideLimits } from './overrides.ts'
import { decideAfterReview } from './reviewer.ts'

/** `toast`: shown to the person as well as logged. */
export type Notice = { toast: boolean; text: string }
export type RequestPlan = { entry: Override; notices: Notice[]; reply: string; pause: boolean }

function textOf(input: Record<string, unknown>, key: string): string | null {
  const value = input[key]
  return typeof value === 'string' ? value : null
}

/** The request a tool input or /tdd pause makes; `target` is the module and path its file resolved to, if any. */
export function requestFrom(input: Record<string, unknown>, by: 'agent' | 'human', target: { module: string | null; path: string | null }): OverrideRequest {
  const scope = (textOf(input, 'scope') ?? '') as OverrideScope
  const pause = scope === 'pause'
  return {
    by,
    scope,
    kind: (textOf(input, 'kind') ?? '') as OverrideKind,
    module: pause ? null : target.module,
    path: pause ? null : target.path,
    reason: textOf(input, 'reason') ?? '',
    until: textOf(input, 'until'),
    minutes: typeof input.minutes === 'number' ? input.minutes : null,
  }
}

/** Why the request is refused before anyone is asked: an incomplete form, or the rising bar. Null when it may go on. */
export function refusal(request: OverrideRequest, record: readonly Override[], nowMs: number, limits: OverrideLimits): string | null {
  const why = checkRequest(request, limits) ?? refuseByBar(record, request, nowMs)
  return why === null ? null : `dope-tdd: override refused: ${why}.`
}

/** A hotfix and a person's own request never go to the model: the first is recovery, the second is the approver. */
export function sendsToModel(request: OverrideRequest, approver: 'human' | 'model'): boolean {
  return approver === 'model' && request.by === 'agent' && request.kind !== 'hotfix'
}

export function planRequest(args: {
  request: OverrideRequest
  record: readonly Override[]
  nowMs: number
  present: boolean
  labelOf: (module: string | null) => string
  review?: Review
  session?: string
}): RequestPlan {
  const { request, record, nowMs, present, review, session } = args
  const decision = review === undefined ? decideAtRequest(request, present) : decideAfterReview(review.verdict, present)
  const entry: Override = {
    ...request,
    ...(session === undefined ? {} : { session }),
    id: `o${nowMs.toString(36)}-${record.length + 1}`,
    atMs: nowMs,
    status: decision.status,
    decidedBy: decision.decidedBy,
    decidedAtMs: decision.status === 'pending' ? null : nowMs,
    endedAtMs: null,
    settledAtMs: null,
    note: review !== undefined && decision.decidedBy === 'model' && decision.status === 'denied' ? review.reason : null,
    edits: [],
    ...(review === undefined ? {} : { review }),
  }
  const label = args.labelOf(request.module)
  const reason = request.reason.trim()
  const pause = entry.status === 'approved' && entry.scope === 'pause'

  if (entry.decidedBy === 'model' && review !== undefined) {
    const byModel = `model ${review.model} (${review.effort})`
    const approved = entry.status === 'approved'
    return {
      entry,
      pause,
      notices: [{ toast: true, text: `⚑ dope-tdd: override ${approved ? 'approved' : 'denied'} by ${byModel} for ${request.kind} on ${label}: "${reason}". ${review.reason}` }],
      reply: approved
        ? `dope-tdd: override approved by ${byModel}: ${review.reason} ${request.scope} on ${label}, recorded in ${OVERRIDES_FILE}.`
        : `dope-tdd: override denied by ${byModel}: ${review.reason} Do that instead; do not work around the guard.`,
    }
  }
  if (entry.status === 'pending') {
    const notes = requestNotes(record, request, nowMs)
    const history = notes.length === 0 ? '' : ` (${notes.join('; ')})`
    const escalated = review === undefined ? '' : ` (the reviewer model escalated: ${review.reason})`
    return {
      entry,
      pause,
      notices: [{ toast: true, text: `⚑ dope-tdd: override needs you. ${request.kind} on ${label}: "${reason}"${history}${escalated}. /tdd approve, or /tdd deny <why>` }],
      reply:
        'dope-tdd: override requested; waiting for a person to approve it. Stop here: tell the user what you asked for and why, and wait for their answer. Do not retry or work around the guard.',
    }
  }
  if (entry.status === 'denied') {
    return {
      entry,
      pause,
      notices: [{ toast: false, text: `dope-tdd: override denied, nobody is here to approve it: ${request.kind} on ${label}: "${reason}"` }],
      reply: 'dope-tdd: override denied: nobody is here to approve it. Stop and report what you needed and why; do not work around the guard.',
    }
  }
  if (entry.decidedBy === 'hotfix rule') {
    return {
      entry,
      pause,
      notices: [
        ...(pause ? [{ toast: true, text: `TDD guard paused for ${request.minutes ?? 0}m` }] : []),
        { toast: true, text: `⚑ dope-tdd: hotfix override on ${label}: "${reason}". Recorded as debt until a test is written.` },
      ],
      reply: `dope-tdd: override approved (hotfix rule): ${request.scope} on ${label}. It is debt in ${OVERRIDES_FILE} until a test is written; end it with /tdd override end ${request.module ?? 'pause'} once one is.`,
    }
  }
  return {
    entry,
    pause,
    notices: pause ? [{ toast: true, text: `TDD guard paused for ${request.minutes ?? 0}m` }] : [],
    reply: pause
      ? `dope-tdd is paused for ${request.minutes ?? 0} minutes (${reason}). It comes back on by itself; /tdd resume ends it sooner. The pause is on the record.`
      : `dope-tdd: override approved: ${request.scope} on ${label}, recorded in ${OVERRIDES_FILE}.`,
  }
}

/** A person's decision on the waiting request: the record with it decided, the reply, and whether it pauses now. */
export function planDecision(
  record: readonly Override[],
  approve: boolean,
  why: string | null,
  nowMs: number,
  labelOf: (module: string | null) => string,
): { record: Override[]; reply: string; pause: boolean } {
  const pending = record.find(o => o.status === 'pending')
  if (pending === undefined) {
    return { record: [...record], reply: 'dope-tdd: no override request is waiting.', pause: false }
  }
  const decided: Override = { ...pending, status: approve ? 'approved' : 'denied', decidedBy: 'human', decidedAtMs: nowMs, note: approve ? null : why }
  return {
    record: record.map(o => (o.id === pending.id ? decided : o)),
    reply: approve
      ? `dope-tdd: override approved: ${decided.scope} on ${labelOf(decided.module)}. Tell the agent to go on.`
      : `dope-tdd: override denied${why === null ? '' : `: ${why}`}. Tell the agent what to do instead.`,
    pause: approve && decided.scope === 'pause',
  }
}

// The override lifecycle (#59, second slice): what the record becomes, and what is said, when a pause runs out, a person
// resumes or ends one, or a shell write spends one. `resume` asks the shell to turn the guard back on.
const MINUTE = 60_000

/** Pauses whose minutes ran out end at their own end time, and each says what happened while it was on. */
export function planExpiry(record: readonly Override[], nowMs: number): { record: Override[]; resume: boolean; summaries: string[] } {
  const expired = expiredPauses(record, nowMs)
  if (expired.length === 0) {
    return { record: [...record], resume: false, summaries: [] }
  }
  const ids = new Set(expired.map(pause => pause.id))
  return {
    record: record.map(o => (ids.has(o.id) ? { ...o, endedAtMs: o.atMs + (o.minutes ?? 0) * MINUTE } : o)),
    resume: true,
    summaries: expired.map(pauseSummary),
  }
}

/** /tdd resume: open pauses close now; a guard paused with none on record (from before) resumes all the same. */
export function planResume(record: readonly Override[], paused: boolean, nowMs: number): { record: Override[]; resume: boolean; reply: string } {
  const open = record.filter(o => o.status === 'approved' && o.scope === 'pause' && o.endedAtMs === null)
  if (open.length === 0 && !paused) {
    return { record: [...record], resume: false, reply: 'dope-tdd is already on.' }
  }
  // Said as the time it actually ran, not the time it was asked for.
  const summaries = open.map(pause => pauseSummary({ ...pause, minutes: Math.max(1, Math.round((nowMs - pause.atMs) / MINUTE)) }))
  return {
    record: open.length === 0 ? [...record] : closePauses(record, nowMs),
    resume: true,
    reply: ['dope-tdd is on: an edit to untested source is refused until its test is written.', ...summaries].join('\n'),
  }
}

/** /tdd override end <module|pause>: a miss lists what is open; ending the pause resumes the guard. */
export function planEnd(record: readonly Override[], target: string | undefined, nowMs: number): { record: Override[]; resume: boolean; reply: string } {
  if (target === undefined || target === '') {
    return { record: [...record], resume: false, reply: 'Name what to end: /tdd override end <module>, or /tdd override end pause.' }
  }
  const ended = endOverride(record, target, nowMs)
  if (ended.every((o, index) => o === record[index])) {
    return { record: [...record], resume: false, reply: `No open override on ${target}. ${endHint(record, nowMs)}` }
  }
  return { record: ended, resume: target === 'pause', reply: `dope-tdd: ended the override on ${target}; the guard is back on it.` }
}

/** Locked modules a shell command writes: one this session's override covers passes and is counted on it. */
export function planShellCover(
  record: readonly Override[],
  locked: readonly string[],
  writes: readonly { path: string; module: string | null }[],
  nowMs: number,
  session: string | undefined,
): { record: Override[]; stillLocked: string[] } {
  let next = [...record]
  const stillLocked: string[] = []
  for (const module of locked) {
    const covering = coveringOverride(next, module, nowMs, session)
    const path = writes.find(write => write.module === module)?.path
    if (covering === null || path === undefined) {
      stillLocked.push(module)
    } else {
      next = recordEdit(next, covering.id, path)
    }
  }
  return { record: next, stillLocked }
}

files.hooks/fileGate.ts:
// The verdict on an Edit or Write before it happens (#59, third slice, 2026-10-18): out of register.tsx, so the gate's
// own catch check covers it. register.tsx gathers the facts (the file's kind and policy, the guard's state, the
// override that covers it), acts on the verdict, and does the writing and the bookkeeping.
import type { Policy } from './config.ts'
import { OVERRIDES_FILE } from './overrides.ts'

export type GateInput = {
  /** The written file, relative to the project root. */
  relativePath: string
  isConfig: boolean
  kind: 'source' | 'test' | 'other'
  /** The source file's policy; null for anything that is not source. */
  policy: Policy | null
  /** The module has a test on record. */
  unlocked: boolean
  /** ...but only through a carry-over from an earlier session, not yet run this session (#54). */
  inherited: boolean
  paused: boolean
  /** This session's approved override that covers the module, if any (overrides.ts, coveringOverride). */
  covering: { id: string } | null
  /** Code the layout pairs with no test (bandModel.ts, countsAsUnwatched). */
  unwatchedCode: boolean
}

export type GateVerdict =
  | { kind: 'deny-record' }
  | { kind: 'exempt' }
  | { kind: 'blocked' }
  | { kind: 'carry-wait' }
  /** `locked`: untested source let through (paused, warn, observe, or an override); `spend`: the override it uses. */
  | { kind: 'go'; locked: boolean; spend: string | null; unwatched: boolean }

export function gateWrite(input: GateInput): GateVerdict {
  // The record is evidence of who approved what: only dope-tdd writes it, whatever the mode.
  if (input.relativePath === OVERRIDES_FILE) {
    return { kind: 'deny-record' }
  }
  if (input.policy === 'exempt') {
    return { kind: 'exempt' }
  }
  const unwatched = input.kind === 'other' && !input.isConfig && input.unwatchedCode
  const locked = input.kind === 'source' && !input.unlocked
  const enforced = input.policy === 'enforce'
  if (locked && enforced && input.covering === null && !input.paused) {
    return { kind: 'blocked' }
  }
  // #54: unlocked only by a carry-over; enforce waits for one run of its test this session, warn reminds after.
  if (input.kind === 'source' && !locked && input.inherited && enforced && !input.paused) {
    return { kind: 'carry-wait' }
  }
  return { kind: 'go', locked, spend: locked && enforced && input.covering !== null ? input.covering.id : null, unwatched }
}

files.hooks/toolResult.ts:
import type { ToolCallResult } from 'claude-code'

export function succeeded(result: ToolCallResult): boolean {
  return result.deny === undefined && result.isError !== true
}

export function withContext(result: ToolCallResult, lines: string[]): ToolCallResult {
  return lines.length === 0 || result.deny !== undefined
    ? result
    : { ...result, context: [...(result.context ?? []), ...lines] }
}

export function tell(quiet: boolean, result: ToolCallResult, lines: string[]): ToolCallResult {
  return quiet ? result : withContext(result, lines)
}

files.hooks/retention.ts:
/**
 * How long a session log under `~/.dope-tdd/sessions` stays: 30 days from its last write. Long enough to read last
 * month's receipts, short enough that they do not pile up.
 */
export const RETENTION_MS = 30 * 24 * 60 * 60_000

/**
 * The folders under `~/.dope-tdd` that are pruned. Never `kept`: a change kept aside is one dope-tdd could not put
 * back, and may be the only copy of someone's work. It is named at every session start instead (`keptNotice`), and
 * only its owner deletes it (decided 2026-10-18, PR #89).
 */
export const PRUNED_FOLDERS: readonly string[] = ['sessions']

const NAMED = 3

/** What to tell the user about changes kept aside, named relative to `~/.dope-tdd/kept`; null when there are none. */
export function keptNotice(paths: readonly string[]): string | null {
  if (paths.length === 0) {
    return null
  }
  const one = paths.length === 1
  const named = paths.slice(0, NAMED).join(', ') + (paths.length > NAMED ? ` and ${paths.length - NAMED} more` : '')
  return (
    `dope-tdd: ${paths.length} change${one ? ' it could not put back is' : 's it could not put back are'} kept in ~/.dope-tdd/kept: ${named}. ` +
    `Look at ${one ? 'it' : 'them'}, then delete ${one ? 'it' : 'them'} yourself; dope-tdd never deletes these.`
  )
}

/** A file dated in the future (clock skew) is not expired: the safe answer for a delete is no. */
export function isExpired(mtimeMs: number, nowMs: number, maxAgeMs: number = RETENTION_MS): boolean {
  return nowMs - mtimeMs > maxAgeMs
}

/**
 * `$.fs` cannot delete, so a stale file is removed by node, the one runtime the plugin already needs for most stacks.
 * The path is an argument, never part of the script: a file name with a quote in it cannot change what runs.
 */
export function pruneArgv(path: string): string[] {
  return ['node', '-e', "require('node:fs').rmSync(process.argv[1], { force: true })", path]
}

files.hooks/checkJournal.ts:
import { storeRoot } from './unlocks.ts'

export const JOURNAL_PREFIX = 'catch-journal:'

export type JournalFile = { path: string; before: string; after: string }

export function isJournalFile(value: unknown): value is JournalFile {
  const file = value as Partial<JournalFile> | null
  return typeof file === 'object' && file !== null && typeof file.path === 'string' && typeof file.before === 'string' && typeof file.after === 'string'
}

/** The journal as stored: the files, and when it was written, so its age is on record. */
export function journalEntry(files: JournalFile[], atMs: number): { files: JournalFile[]; atMs: number } {
  return { files, atMs }
}

/** A journal younger than this may belong to a check still running in another session, so it is not reported. */
export const RUNNING_GRACE_MS = 15 * 60_000

const NAMED = 3

/**
 * Another project's interrupted catch check, as it is told to the user. A session never repairs another project (#89:
 * an agent changes only what it owns); it reports, so the owner repairs it by opening a session there. A journal with
 * no time is from an earlier build, so its check is long over. Null when there is nothing to report.
 */
export function elsewhereNotice(found: readonly { paths: readonly string[]; atMs?: number }[], nowMs: number): string | null {
  const paths = found.filter(journal => journal.atMs === undefined || nowMs - journal.atMs > RUNNING_GRACE_MS).flatMap(journal => journal.paths)
  if (paths.length === 0) {
    return null
  }
  const named = paths.slice(0, NAMED).join(', ') + (paths.length > NAMED ? ` and ${paths.length - NAMED} more` : '')
  return (
    `dope-tdd: a catch check in another project was interrupted and may have left ${named} reverted. ` +
    `Open a session in that project and dope-tdd puts ${paths.length === 1 ? 'it' : 'them'} back; nothing there was changed from here.`
  )
}

export function journalFiles(value: unknown): JournalFile[] | null {
  const journal = value as { files?: unknown } | null
  return typeof journal === 'object' && journal !== null && Array.isArray(journal.files) ? journal.files.filter(isJournalFile) : null
}

export function journalKeyFor(root: string, module: string): string {
  return `${JOURNAL_PREFIX}${storeRoot(root)}:${module}`
}

/**
 * One catch-check lock per checkout, across every session on the machine.
 * The store is shared but its get-then-set is not atomic (the mods docs say
 * so), so the lock itself is a git ref updated by compare-and-swap: creating
 * it succeeds for exactly one session, an expired one is taken over only by
 * naming its exact old value, and a session can release only its own.
 * refs/worktree/ refs are per checkout, which is the right scope: two
 * worktrees of one repository revert different files. The store keeps a copy
 * so every guard can see the lock without starting git on each tool call.
 */
export const SHARED_LOCK_REF = 'refs/worktree/dope-tdd-check'

export type SharedLock = { kind: 'acquired'; sha: string } | { kind: 'busy'; module: string } | { kind: 'unavailable' }

export function sharedLockKey(root: string): string {
  return `check-lock:${storeRoot(root)}`
}

export function parseLock(text: string | undefined): { module: string; sinceMs: number } | null {
  try {
    const value = JSON.parse(text ?? '') as { module?: unknown; sinceMs?: unknown }
    return typeof value.module === 'string' && typeof value.sinceMs === 'number' ? { module: value.module, sinceMs: value.sinceMs } : null
  } catch {
    return null
  }
}

files.hooks/layout.ts:
/**
 * Where tests live relative to sources, as two path templates. Tokens:
 * `{module}` (the part shared by a source and its test, may contain slashes),
 * `{dir}` and `{name}` (the module split at its last slash; `{dir}` keeps its
 * trailing slash or is empty), `{ext}` (the stack's extensions: for Node ts,
 * tsx, js, jsx, mts, cts, mjs, cjs; for Python py; for Godot gd; and so on,
 * see `stacks.ts`).
 */

export type NodeLayoutName = 'mirror' | 'colocated' | '__tests__'
export type LayoutName = NodeLayoutName | 'custom' | string

/**
 * `pairing` is how a test finds its source. By path (the default) the module is
 * the path both templates share, so tests mirror the source tree. By name the
 * module is the file's basename alone: `scripts/show/BeatDeck.cs` and
 * `test/BeatDeckTest.cs` meet at `BeatDeck` wherever each sits, which is how
 * gdUnit4, pytest's flat `tests/` folders and many Node projects lay tests out.
 */
export type Pairing = 'path' | 'name'

export type Layout = { name: LayoutName; source: string; test: string; pairing?: Pairing; displayExt?: string }

/** A folder of the project whose files follow a layout of their own; its templates start inside the folder. */
export type FolderLayout = { folder: string; layout: Layout }

export const LAYOUTS: Readonly<Record<NodeLayoutName, Layout>> = {
  mirror: { name: 'mirror', source: 'src/{module}.{ext}', test: 'tests/{module}.test.{ext}' },
  colocated: { name: 'colocated', source: 'src/{module}.{ext}', test: 'src/{module}.test.{ext}' },
  __tests__: { name: '__tests__', source: 'src/{module}.{ext}', test: 'src/{dir}__tests__/{name}.test.{ext}' },
}

export const MIRROR: Layout = LAYOUTS.mirror

/** What `{ext}` accepts when no stack is named: the Node extensions. */
export const NODE_EXTS: readonly string[] = ['ts', 'tsx', 'js', 'jsx', 'mts', 'cts', 'mjs', 'cjs']

const TOKEN = /\{(module|dir|name|ext)\}/g
const DISPLAY_EXT = 'ts(x)'

function escape(literal: string): string {
  return literal.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function tokenPattern(token: string, exts: readonly string[]): string {
  switch (token) {
    case 'module':
      return '(?<module>.+?)'
    case 'dir':
      return '(?<dir>(?:[^/]+/)*)'
    case 'name':
      return '(?<name>[^/]+?)'
    default:
      return `(?<ext>(?:${exts.map(escape).join('|')}))`
  }
}

export function templateToRegExp(template: string, exts: readonly string[] = NODE_EXTS): RegExp {
  let source = '^'
  let last = 0
  for (const match of template.matchAll(TOKEN)) {
    const at = match.index ?? 0
    source += escape(template.slice(last, at)) + tokenPattern(match[1] ?? '', exts)
    last = at + match[0].length
  }
  return new RegExp(`${source}${escape(template.slice(last))}$`)
}

/** The module a relative path names under this template, or null when the path is not of that shape. */
export function matchTemplate(template: string, relative: string, exts: readonly string[] = NODE_EXTS): { module: string; ext: string } | null {
  const groups = templateToRegExp(template, exts).exec(relative)?.groups
  if (groups === undefined) {
    return null
  }
  const module = groups.module ?? `${groups.dir ?? ''}${groups.name ?? ''}`
  return module === '' ? null : { module, ext: groups.ext ?? '' }
}

export function fillTemplate(template: string, module: string, ext: string): string {
  const slash = module.lastIndexOf('/')
  const dir = slash === -1 ? '' : module.slice(0, slash + 1)
  const name = slash === -1 ? module : module.slice(slash + 1)
  return template.replace(TOKEN, (_whole, token: string) => (token === 'module' ? module : token === 'dir' ? dir : token === 'name' ? name : ext))
}

/** The test path as a person reads it in a message: `tests/utils/a.test.ts(x)`. */
export function describeTestPath(layout: Layout, module: string, displayExt: string = DISPLAY_EXT): string {
  return fillTemplate(layout.test, module, displayExt)
}

/** The source path without its extension, as a person reads it: `src/utils/a`. */
export function describeSourcePath(layout: Layout, module: string): string {
  return fillTemplate(layout.source, module, '').replace(/\.$/, '')
}

export function firstSegment(template: string): string {
  return template.split('/')[0] ?? template
}

/** The directory a template starts with when that is a literal, or null when it starts with a token (`{module}.gd` sits anywhere). */
export function literalRoot(template: string): string | null {
  const segment = firstSegment(template)
  return segment.includes('{') ? null : segment
}

/** A template is usable when it has an extension and names the module one way or the other; by name, `{name}` alone is enough. */
export function templateError(template: string, pairing: Pairing = 'path'): string | null {
  if (!template.includes('{ext}')) {
    return `${template} must contain {ext}`
  }
  if (pairing === 'name') {
    return template.includes('{name}') || template.includes('{module}') ? null : `${template} must contain {name}`
  }
  const namesModule = template.includes('{module}') || (template.includes('{dir}') && template.includes('{name}'))
  return namesModule ? null : `${template} must contain {module}, or both {dir} and {name}`
}

/** The last segment of a module id: what a name-paired layout keys on. */
export function baseName(module: string): string {
  return module.slice(module.lastIndexOf('/') + 1)
}

